const API_OPERACIONES_ADMIN = '../Api_Operaciones/vista.php';
async function apiAdmin(accion, datos = null) { const opciones = { headers: { Accept: 'application/json' } }; if (datos) { opciones.method = 'POST'; opciones.headers['Content-Type'] = 'application/json'; opciones.body = JSON.stringify(datos); } const respuesta = await fetch(`${API_OPERACIONES_ADMIN}?accion=${accion}`, opciones); const resultado = await respuesta.json(); if (!respuesta.ok || !resultado.ok) throw new Error(resultado.mensaje || 'No se pudo completar la operación.'); return resultado; }
function opciones(elemento, datos, valor, texto) { elemento.innerHTML = datos.map((dato) => `<option value="${dato[valor]}">${dato[texto]}</option>`).join('') || '<option value="">Sin datos disponibles</option>'; }
async function cargarAsignaciones() { const [rutas, camiones, conductores, peones] = await Promise.all([apiAdmin('rutas'), apiAdmin('camiones'), apiAdmin('trabajadores&rol=conductor'), apiAdmin('trabajadores&rol=peon')]); opciones(rutaParada, rutas.rutas, 'id_ruta', 'nombre'); opciones(rutaAsignacion, rutas.rutas, 'id_ruta', 'nombre'); camionAsignacion.innerHTML = camiones.camiones.map((c) => `<option value="${c.id_camion}">${c.matricula} · ${c.modelo}</option>`).join(''); opciones(conductorAsignacion, conductores.trabajadores, 'ci', 'nombre'); opciones(peonAsignacion, peones.trabajadores, 'ci', 'nombre'); }
formRuta.addEventListener('submit', async (e) => { e.preventDefault(); try { mensajeRutas.textContent = (await apiAdmin('crear_ruta', { nombre: nombreRutaAdmin.value, zona: zonaRutaAdmin.value })).mensaje; e.currentTarget.reset(); cargarAsignaciones(); } catch (error) { mensajeRutas.textContent = error.message; } });
formParada.addEventListener('submit', async (e) => { e.preventDefault(); try { mensajeRutas.textContent = (await apiAdmin('crear_parada', { id_ruta: rutaParada.value, ubicacion: ubicacionParada.value, descripcion: descripcionParada.value, orden: ordenParada.value })).mensaje; e.currentTarget.reset(); } catch (error) { mensajeRutas.textContent = error.message; } });
formAsignacion.addEventListener('submit', async (e) => { e.preventDefault(); try { mensajeRutas.textContent = (await apiAdmin('asignar_ruta', { id_ruta: rutaAsignacion.value, id_camion: camionAsignacion.value, ci_conductor: conductorAsignacion.value, ci_peon: peonAsignacion.value, fecha: fechaAsignacion.value })).mensaje; } catch (error) { mensajeRutas.textContent = error.message; } });
apiAdmin('reporte_admin').then(({ reporte }) => { reporteAdmin.textContent = `Rutas asignadas: ${reporte.rutas_hoy} · Paradas recolectadas: ${reporte.recolecciones_hoy} · Incidencias pendientes: ${reporte.incidencias_pendientes} · Ingresos: ${Number(reporte.ingresos_hoy).toLocaleString('es-UY')} kg`; }).catch((error) => { reporteAdmin.textContent = error.message; });
fechaAsignacion.value = new Date().toISOString().slice(0, 10); cargarAsignaciones().catch((error) => { mensajeRutas.textContent = error.message; });
